<?php
declare(strict_types=1);namespace App;use PDO;final class MailRepository{public function __construct(public readonly PDO$db){}public function mailbox(array$u):array{$s=$this->db->prepare('SELECT * FROM mailboxes WHERE user_id=?');$s->execute([$u['id']]);$m=$s->fetch();if(!$m)throw new ApiException(403,'mailbox_required','A mailbox is required.');return$m;}public function owned(string$table,int$id,array$u,string$fk='mailbox_id'):array{$m=$this->mailbox($u);$s=$this->db->prepare("SELECT * FROM {$table} WHERE id=? AND {$fk}=?");$s->execute([$id,$m['id']]);$r=$s->fetch();if(!$r)throw new ApiException(404,'not_found','Resource not found.');return$r;}public function message(int$id,array$u):array{return$this->owned('messages',$id,$u);}public function adminDomains(array$u):array{if($u['role']==='platform_admin')return$this->rows('SELECT * FROM domains ORDER BY id');return$this->rows('SELECT d.* FROM domains d JOIN domain_admins a ON a.domain_id=d.id WHERE a.user_id=? ORDER BY d.id',[$u['id']]);}public function adminDomain(int$id,array$u):array{if($u['role']==='platform_admin')$s=$this->db->prepare('SELECT * FROM domains WHERE id=?');else{$s=$this->db->prepare('SELECT d.* FROM domains d JOIN domain_admins a ON a.domain_id=d.id WHERE d.id=? AND a.user_id=?');}$s->execute($u['role']==='platform_admin'?[$id]:[$id,$u['id']]);$d=$s->fetch();if(!$d)throw new ApiException(404,'not_found','Resource not found.');return$d;}public function rows(string$sql,array$args=[]):array{$s=$this->db->prepare($sql);$s->execute($args);return$s->fetchAll();}public function audit(int$actor,?int$domain,string$action,string$details):void{$this->db->prepare('INSERT INTO audit_events(actor_id,domain_id,action,details,created_at) VALUES(?,?,?,?,?)')->execute([$actor,$domain,$action,$details,gmdate(DATE_ATOM)]);}}
